import java.util.concurrent.*;

class SleepingTraveler {
    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        // Do something here to represent tallying lanterns.
        System.out.println("Tally some sheep.");
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        SleepingTraveler traveler = new SleepingTraveler();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Submit two tasks to the executor service.
        Future<?> future1 = executor.submit(traveler::tryToSleep);
        Future<?> future2 = executor.submit(traveler::tryToSleep);

        // Wait for both tasks to finish.
        future1.get();
        future2.get();

        executor.shutdown();
    }
}

