    public static void main(String[] args) throws Exception {
        Traveler traveler = new Traveler();
        new Thread(() -> {
            try { traveler.tryToSleep(); } catch (InterruptedException | ExecutionException e) {}
        }).start();
        // Simulate the traveller awakening after some time.
        Thread.sleep(5000);
        synchronized (traveler) {
            traveler.asleep = true;
        }
    }
}

