import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.time.*;

class Main {
    public static void main(String[] args) throws InterruptedException, TimeoutException {
        // Create lockers
        Locker sourceLocker = new Locker("Source", 10);
        Locker targetLocker = new Locker("Target", 5);

        // Start thread to move parcels
        ExecutorService executor = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 5; i++) {
            final int quantityToMove = i + 1;
            executor.execute(() -> {
                try {
                    move(sourceLocker, targetLocker, quantityToMove, 1, TimeUnit.SECONDS);
                } catch (InterruptedException | TimeoutException e) {
                    System.err.println("Failed to move " + quantityToMove + " parcels: " + e.getMessage());
                }
            });
        }

        // Shutdown the executor service to prevent new tasks from being submitted and wait for existing tasks to terminate
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }

    static boolean move(Locker sourceLocker, Locker targetLocker, int quantityToMove, long timeout, TimeUnit timeUnit) throws InterruptedException, TimeoutException {
        // Create locks and use tryLock with a timeout to acquire both lockers
        ReentrantLock sourceLock = sourceLocker.getLock();
        ReentrantLock targetLock = targetLocker.getLock();

        if (sourceLock.tryLock(timeout, timeUnit) && targetLock.tryLock(timeout, timeUnit)) {
            try {
                // Check if there are enough items in the source locker before proceeding with the move
                ParcelCount sourceParcels = sourceLocker.getParcels();

                if (sourceParcels.hasAtLeast(quantityToMove)) {
                    // Simulate a random pause for deadlock avoidance mechanism
                    Thread.sleep(calculateRandomDelay(50));

                    // Move parcels
                    sourceLock.lock();
                    targetLock.lock();

                    sourceParcels.remove(quantityToMove);
                    targetLocker.getParcels().add(quantityToMove);

                    System.out.println("Moved " + quantityToMove + " parcels from " + sourceLocker.getName() + " to " + targetLocker.getName());
                    return true;
                } else {
                    throw new NotEnoughItemsException("Not enough items in the source locker");
                }
            } finally {
                // Unlock the locks in all cases, even if an exception was thrown
                sourceLock.unlock();
                targetLock.unlock();
            }
        } else {
            return false;
        }
    }

    static long calculateRandomDelay(long fixedDelay) {
        Random random = new Random();
        return fixedDelay + random.nextInt(10); // Adds a delay between 0 and 9 to the fixed delay
    }
}

class Locker {
    private final String name;
    private ParcelCount parcels;
    private ReentrantLock lock = new ReentrantLock();

    public Locker(String name, int initialParcels) {
        this.name = name;
        this.parcels = new ParcelCount(initialParcels);
    }

    public String getName() { return name; }
    public ReentrantLock getLock() { return lock; }
    public ParcelCount getParcels() { return parcels; }
}

class ParcelCount {
    private int count = 0;

    public ParcelCount(int initialCount) { this.count = initialCount; }

    public void add(int amount) {
        if (amount < 0) throw new IllegalArgumentException("Amount must be non-negative");
        count += amount;
    }

    public boolean hasAtLeast(int amount) { return count >= amount; }

    public void remove(int amount) throws NotEnoughItemsException {
        if (amount < 0) throw new IllegalArgumentException("Amount must be non-negative");

        if (!hasAtLeast(amount)) 
            throw new NotEnoughItemsException("Not enough items");

        count -= amount;
    }
}

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) { super(message); }
}

import java.util.Random;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

public class LockerAndParcel {
    static class ParcelCount {
        private int count = 0;

        public void add(int value) {
            this.count += value;
        }

        public boolean remove(int value) {
            if (this.count < value) return false;
            this.count -= value;
            return true;
        }
    }

    static class Locker {
        private ParcelCount parcelCount = new ParcelCount();
        private ReentrantLock locker = new ReentrantLock();

        public boolean tryAdd(int count) {
            if (locker.tryLock()) {
                try {
                    parcelCount.add(count);
                } finally {
                    locker.unlock();
                }
                return true;
            }
            return false;
        }

        public boolean tryRemove(int count) throws NotEnoughItemsException {
            if (locker.tryLock()) {
                try {
                    if (!parcelCount.remove(count)) throw new NotEnoughItemsException("Not enough items in the locker");
                } finally {
                    locker.unlock();
                }
                return true;
            }
            return false;
        }
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static Locker source = new Locker();
    static Locker target = new Locker();

    private static final Random rand = new Random();

    public static void main(String[] args) throws InterruptedException {
        Thread.sleep(1000); // Adding a fixed delay to simulate some work being done before acquiring locks

        int quantityToMove = 5;
        long timeoutDuration = rand.nextInt(2000); // Generate random timeout duration between 0 and 2 seconds

        move(source, target, quantityToMove, timeoutDuration, TimeUnit.MILLISECONDS);
    }

    public static boolean move(Locker source, Locker target, int quantityToMove, long timeout, TimeUnit timeunit) {
        try {
            if (source.locker.tryLock(timeout, timeunit)) {
                try {
                    if (target.locker.tryLock(timeout, timeunit)) {
                        try {
                            if (!source.tryRemove(quantityToMove)) throw new NotEnoughItemsException("Not enough items in the source locker");
                            target.tryAdd(quantityToMove);
                        } finally {
                            target.locker.unlock();
                        }
                    } else {
                        return false; // Target lock not acquired within timeout period
                    }
                } finally {
                    source.locker.unlock();
                }
            } else {
                return false; // Source lock not acquired within timeout period
            }
        } catch (NotEnoughItemsException e) {
            System.out.println(e.getMessage());
        }

        return true;
    }
}

