import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class DeadlockAvoidance {
    private final Random random = new Random();

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        DeadlockAvoidance deadlockAvoidance = new DeadlockAvoidance();
        Container originContainer = new Container("Origin", 5);
        Container targetContainer = new Container("Target", 0);

        ExecutorService executorService = Executors.newFixedThreadPool(3);

        for (int i = 1; i <= 2; ++i) {
            Future<Boolean> future = executorService.submit(() -> deadlockAvoidance.swap(originContainer, targetContainer, 1, 500, TimeUnit.MILLISECONDS));
            System.out.println("Swap " + i + ": " + (future.get() ? "success" : "fail"));
        }

        executorService.shutdown();
    }

    public boolean swap(Container origin, Container target, int numElements, long timeout, TimeUnit unit) {
        ReentrantLock[] locks = new ReentrantLock[2];
        locks[0] = origin.getLock();
        locks[1] = target.getLock();

        while (true) {
            try {
                if(tryAcquireLocks(locks, timeout, unit)) {
                    if(origin.getElementCount().get() >= numElements) {
                        origin.removeElements(numElements);
                        target.addElements(numElements);
                        return true;
                    } else {
                        throw new InsufficientElementsException();
                    }
                }
            } catch (InsufficientElementsException | InterruptedException e) {
                unlockLocks(locks, 0);
                break;
            }
        }

        return false;
    }

    private boolean tryAcquireLocks(ReentrantLock[] locks, long timeout, TimeUnit unit) throws InsufficientElementsException, InterruptedException {
        long fixedDelay = random.nextInt((int) (timeout / 5));

        for (int i = 0; i < locks.length; ++i) {
            if (!locks[i].tryLock(getRandomLongInRange(fixedDelay/2, fixedDelay), unit)) {
                unlockLocks(locks, i);
                return false;
            }
        }

        Thread.sleep(random.nextInt((int) (timeout - fixedDelay)));
        return true;
    }

    private void unlockLocks(ReentrantLock[] locks, int lastIndexToUnlock) {
        for (int i = lastIndexToUnlock; i >= 0; --i) {
            if(locks[i].isHeldByCurrentThread()) {
                locks[i].unlock();
            }
        }
    }

    private long getRandomLongInRange(long min, long max) {
        return random.nextInt((int)(max - min + 1)) + min;
    }

    static class ElementCount {
        private int count = 0;

        public void increment() {
            this.count++;
        }

        public void decrement() {
            if (this.count > 0) {
                this.count--;
            }
        }

        public int get() {
            return this.count;
        }
    }

    static class Container {
        private final ReentrantLock lock = new ReentrantLock();
        private final String name;
        private ElementCount elementCount;

        public Container(String name, int count) {
            this.name = name;
            this.elementCount = new ElementCount();

            for (int i = 0; i < count; ++i) {
                this.addElements(1);
            }
        }

        public void addElements(int num) {
            while (num > 0) {
                elementCount.increment();
                num--;
            }
        }

        public void removeElements(int num) {
            while (num > 0 && this.elementCount.get() > 0) {
                elementCount.decrement();
                num--;
            }
        }

        public ElementCount getElementCount() {
            return elementCount;
        }

        public ReentrantLock getLock() {
            return lock;
        }
    }

    static class InsufficientElementsException extends Exception {}
}

