public class ConcurrencyDeadlockAvoidance {

    private static class Container {
        String name;
        int capacity;
        Lock lock = new ReentrantLock();

        public Container(String name, int capacity) {
            this.name = name;
            this.capacity = capacity;
        }

        public boolean tryAddItem() {
            if (this.capacity > 0) {
                this.capacity--;
                return true;
            } else {
                return false;
            }
        }
    }

    private static class ElementCount {
        Container origin, target;
        int count;

        public ElementCount(Container origin, Container target, int count) {
            this.origin = origin;
            this.target = target;
            this.count = count;
        }
    }

    private static class InsufficientElementsException extends Exception {}

    private static void swapItems(ElementCount elementCount, long timeout, TimeUnit timeUnit) throws InterruptedException {
        Random random = new Random();

        while (true) {
            if (elementCount.origin.lock.tryLock(timeout, timeUnit)) {
                try {
                    if (elementCount.target.lock.tryLock(timeout, timeUnit)) {
                        try {
                            if (!swapIfPossible(elementCount)) {
                                throw new InsufficientElementsException();
                            }
                            return;
                        } finally {
                            elementCount.target.lock.unlock();
                        }
                    }
                } finally {
                    elementCount.origin.lock.unlock();
                }
            } else {
                Thread.sleep(randomDelay(random, 100L)); // fixed delay of up to 100ms plus random jitter
            }
        }
    }

    private static boolean swapIfPossible(ElementCount elementCount) throws InsufficientElementsException {
        if (elementCount.origin.capacity >= elementCount.count) {
            for (int i = 0; i < elementCount.count; i++) {
                elementCount.origin.tryAddItem();
                elementCount.target.tryAddItem();
            }
            return true;
        } else {
            throw new InsufficientElementsException();
        }
    }

    private static long randomDelay(Random random, long fixed) {
        return fixed + random.nextLong(fixed);
    }

