            }
        } catch (NotEnoughWidgetsException e) {
            System.err.println(e.getMessage());
        } finally {
            executor.shutdown();
        }
    }

    private static boolean moveWidgetsConcurrently(Bin sourceBin, Bin targetBin, int numWidgets, long timeout, ChronoUnit unit) throws NotEnoughWidgetsException {
        Future<Boolean> future = executor.submit(() -> 
            acquireLocksAndMove(sourceBin, targetBin, numWidgets, timeout, unit)); // Submit the task to the thread pool and get a future representing the result

        try {
            return future.get(); // Wait for the result
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean acquireLocksAndMove(Bin sourceBin, Bin targetBin, int numWidgets, long timeout, ChronoUnit unit) throws NotEnoughWidgetsException {
        ReentrantLock sourceLock = new ReentrantLock();
        ReentrantLock targetLock = new ReentrantLock();

        try {
            if (sourceLock.tryLock(timeout, randomFixedDelay(), unit)) { // Acquire the source bin lock with a timeout and delay
                try {
                    if (targetLock.tryLock(timeout, randomVariableDelay(), unit)) { // Acquire the target bin lock with a timeout and delay
                        if (sourceBin.hasEnoughWidgets(numWidgets)) {
                            sourceBin.removeWidgets(numWidgets);
                            targetBin.addWidgets(numWidgets);

                            return true; // Successful move
                        } else {
                            throw new NotEnoughWidgetsException("Not enough widgets in the source bin.");
                        }
                    }
                } finally {
                    if (targetLock.isHeldByCurrentThread()) { // If we acquired the lock, release it
                        targetLock.unlock();
                    }
                }
            } 
        } finally {
            if (sourceLock.isHeldByCurrentThread()) { // If we acquired the lock, release it
                sourceLock.unlock();
            }
        }

        return false; // Failed to acquire both locks within timeout
    }

    private static long randomFixedDelay() {
        return new Random().nextInt(50) + 50; // A delay of 50-100 milliseconds
    }

    private static long randomVariableDelay() {
        return (long)(new Random().nextDouble() * 100) + 100; // A delay of 100-200 milliseconds
    }
