import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

class SafePoint {
    private int x;
    private int y;

    public SafePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public synchronized void setX(int x) {
        this.x = x;
    }

    public synchronized void setY(int y) {
        this.y = y;
    }

    public synchronized int getX() {
        return x;
    }

    public synchronized int getY() {
        return y;
    }
}

class PublishingVehicleTracker {
    private ConcurrentHashMap<String, SafePoint> vehicleCoordinates = new ConcurrentHashMap<>();

    public void updateCoordinate(String vehicleId, int x, int y) throws IllegalArgumentException {
        if (vehicleCoordinates.get(vehicleId) == null) throw new IllegalArgumentException("Vehicle does not exist");

        SafePoint safePoint = vehicleCoordinates.get(vehicleId);
        synchronized(safePoint) {
            safePoint.setX(x);
            safePoint.setY(y);
        }
    }

    public void addVehicle(String vehicleId, int x, int y) {
        vehicleCoordinates.putIfAbsent(vehicleId, new SafePoint(x, y));
    }

    public Map<String, SafePoint> getVehicles() {
        return Collections.unmodifiableMap(vehicleCoordinates);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();

        // Add vehicles
        tracker.addVehicle("vehicle1", 5, 5);
        tracker.addVehicle("vehicle2", 10, 10);

        // Update vehicle coordinates concurrently using threads
