        vehicleMap.get(id).setXY(x, y);
    }

    public synchronized String getPosition(String id) throws NoSuchElementException {
        if(!vehicleMap.containsKey(id)) throw new NoSuchElementException("No such vehicle: " + id);

        return vehicleMap.get(id).get();
    }

    public synchronized Map<String, SafePoint> getPositions() {
        return Collections.unmodifiableMap(new HashMap<>(vehicleMap));
    }
