        if(!vehiclePositions.containsKey(vehicleId)) {
            throw new IllegalArgumentException("No such Vehicle ID: " + vehicleId);
        }

        return vehiclePositions.get(vehicleId);
    }

    public void updatePositionOfVehicle(final String vehicleId, final SafePoint newCoordinates) {
        if(!vehiclePositions.containsKey(vehicleId)) {
            throw new IllegalArgumentException("No such Vehicle ID: " + vehicleId);
        }

        executor.execute(() -> {
            vehiclePositions.computeIfPresent(vehicleId, (k, v) -> newCoordinates);
        });
    }

    public void addVehiclePosition(final String vehicleId, final SafePoint initialCoordinates) {
        if(vehiclePositions.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle ID already exists: " + vehicleId);
        }

        executor.execute(() -> {
            vehiclePositions.putIfAbsent(vehicleId, initialCoordinates);
        });
    }

    public void stopTracking() {
        if(executor != null) {
            executor.shutdown();
        }
    }
