import java.util.*;
import java.util.concurrent.*;

enum Constellation {
    Aquarius, Pisces, Aries, Taurus, Gemini, Cancer, Leo, Virgo, Libra, Scorpio, Sagittarius, Capricorn
}

enum Resonance {
    Light, Dark
}

class Rune implements Comparable<Rune>{
    private Constellation constellation;
    private Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }

    @Override
    public int compareTo(Rune other) {
        if (this.constellation == other.constellation) {
            return this.resonance.compareTo(other.resonance);
        } else {
            return this.constellation.compareTo(other.constellation);
        }
    }
}

class Harmony {
    private final Rune rune1, rune2;

    public Harmony(Rune rune1, Rune rune2) {
        this.rune1 = rune1;
        this.rune2 = rune2;
    }

    @Override
    public String toString() {
        return "Harmony of " + rune1.getConstellation().toString() + " with resonances " + 
            rune1.getResonance().toString() + " and " + rune2.getResonance().toString();
    }
}

class Grimoire {
    private final List<Harmony> harmonies;

    public Grimoire(List<Harmony> harmonies) {
        this.harmonies = harmonies;
    }

    @Override
    public String toString() {
        return "Grimoire with harmonies: " + harmonies.toString();
    }
}

public class Main {
    private static ExecutorService executor = Executors.newFixedThreadPool(3);

    public static void main(String[] args) throws Exception {
        List<Rune> runes = Arrays.asList(
