import java.util.*;
import java.util.concurrent.*;

enum Constellation {
    FIR, WATER, EARTH, AIR;
}

enum Resonance {
    AFFIRMING, NEGATIVE;
}

class Rune {
    private final Constellation constellation;
    private final Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }
}

class HarmonyHelper implements Runnable {
    private final Queue<Rune> runes;
    private static int harmonyCount = 0;

    public HarmonyHelper(Queue<Rune> runes) {
        this.runes = runes;
    }

    @Override
    public void run() {
        synchronized (HarmonyHelper.class) {
            while (!runes.isEmpty()) {
                Rune r1 = runes.poll();
                if (!runes.isEmpty()) {
                    Rune r2 = runes.peek();
                    if (r1.getConstellation() == r2.getConstellation() && r1.getResonance() != r2.getResonance()) {
                        runes.poll();  // remove the second rune from queue as it forms a harmony
                        harmonyCount++;
                    }
                }
            }
        }
    }

    public static int getHarmonyCount() {
        return harmonyCount;
    }
}

public class Main {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public void channelTheGrimoire(Collection<Rune> runes) throws InterruptedException, ExecutionException {
        Comparator<Rune> comparator = Comparator.comparing(Rune::getConstellation).thenComparing(Rune::getResonance);
        Queue<Rune> sortedRunes = new PriorityQueue<>(comparator);
        sortedRunes.addAll(runes);

        List<Future<?>> futures = new ArrayList<>();
        while (!sortedRunes.isEmpty()) {
            Future<?> future = executor.submit(new HarmonyHelper(sortedRunes));
            futures.add(future);
        }

        for (Future<?> future : futures) {
            future.get();
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Main main = new Main();

        List<Rune> runes = Arrays.asList(new Rune(Constellation.FIR, Resonance.AFFIRMING), 
                                     new Rune(Constellation.WATER, Resonance.NEGATIVE),
                                     new Rune(Constellation.EARTH, Resonance.AFFIRMING),
                                     new Rune(Constellation.FIR, Resonance.NEGATIVE));

        main.channelTheGrimoire(runes);
        System.out.println("Number of valid harmonies: " + HarmonyHelper.getHarmonyCount());
    }
