class Grimoire implements Runnable {
    private ConcurrentLinkedQueue<Rune> runes;
    private ConcurrentLinkedDeque<Harmony> harmonies = new ConcurrentLinkedDeque<>();

    public Grimoire(ConcurrentLinkedQueue<Rune> runes) {
        this.runes = runes;
    }

    @Override
    public void run() {
        while (!runes.isEmpty()) 
            harmonize();
    }

    private synchronized void harmonize() {
        List<Rune> candidates = new ArrayList<>();

        Rune nextRune;
        while ((nextRune = runes.poll()) != null) 
            candidates.add(nextRune);

        Collections.sort(candidates);

        Harmony harmony = new Harmony();
        for (int i = 0; i < candidates.size() - 1; i++) {
            Rune currentRune = candidates.get(i), nextRune = candidates.get(i + 1);

            if (currentRune.constellation == nextRune.constellation && currentRune.resonance != nextRune.resonance) {
                harmony.addRune(currentRune);
                i++;  // to skip the matched rune in the next step
            }
        }

        harmonies.offerLast(harmony);
    }

    public int getHarmonizationCount() {
        return harmonies.size();
    }
}

