import java.util.concurrent.*;

interface Vision { }

class VisionCastException extends Exception { 
    public VisionCastException(String message, Throwable cause) { super(message, cause); }
}

class DreamWeaver {
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private Future<Vision> future;

    public void start() { 
        Callable<Vision> callableTask = () -> loadVision(); 
        future = executor.submit(callableTask); 
    }

    public Vision get() throws VisionCastException, ExecutionException, InterruptedException {
        try { return future.get(); }
        catch (ExecutionException | InterruptedException e) {
            if (e.getCause() instanceof VisionCastException) throw (VisionCastException) e.getCause();
            else throw new VisionCastException("Error in fetching vision", e);
        }
