        Objects.requireNonNull(source);
        Objects.requireNonNull(destination);

        if (amount < 0) throw new IllegalArgumentException("Amount cannot be negative");

        // Lock vaults in consistent order
        Vault first = source.getHash() < destination.getHash() ? source : destination;
        Vault second = source.getHash() > destination.getHash() ? source : destination;

        synchronized (first) {
            synchronized (second) {
                // Check for sufficient treasure before performing debit and credit operations
                source.debit(amount);
                destination.credit(amount);
            }
        }
    }
