    }

    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        if (this.essence == expectedEssence) {
            this.essence = newEssence;
        }
        return this.essence;
    }

    public synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
        if (this.essence == expectedEssence) {
            this.essence = newEssence;
            return true;
        }
        return false;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
