        ExecutorService executor = Executors.newFixedThreadPool(2);

        Future<?> future1 = executor.submit(() -> {
            for (int i = 0; i < 5; ++i) {
                mysticCounter.compareAndSwap(mysticCounter.get(), mysticCounter.get() + 1);
            }
        });

        Future<?> future2 = executor.submit(() -> {
            for (int i = 0; i < 5; ++i) {
                mysticCounter.compareAndSwap(mysticCounter.get(), mysticCounter.get() + 1);
            }
        });

        future1.get();
        future2.get();

        System.out.println("Final essence value: " + mysticCounter.get());

        executor.shutdown();
