import java.util.*;
import java.util.concurrent.*;
import java.lang.reflect.Field;

class MutableOrb {
    private int shimmerX, shimmerY;

    public MutableOrb(int x, int y) {
        this.shimmerX = x;
        this.shimmerY = y;
    }

    public void setShimmerX(int shimmerX) {
        this.shimmerX = shimmerX;
    }

    public void setShimmerY(int shimmerY) {
        this.shimmerY = shimmerY;
    }
}

class ChronomanticDragonTracker {

    private final ConcurrentHashMap<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(ConcurrentHashMap<String, MutableOrb> constellation) {
        this.constellation = new ConcurrentHashMap<>(deepClone(constellation));
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(this.constellation));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        if (constellation.containsKey(sigil)) {
            return deepClone(constellation.get(sigil));
        } else {
            return null;
        }
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (constellation.containsKey(sigil)) {
            MutableOrb orb = constellation.get(sigil);
            orb.setShimmerX(shimmerX);
            orb.setShimmerY(shimmerY);
        } else {
            throw new IllegalArgumentException("Sigil not found");
        }
    }

    private static <K, V> ConcurrentHashMap<K,V> deepClone(ConcurrentHashMap<K,V> map) {

        try {

            // Create a new instance from the object's class and constructor.
            Constructor<? extends Object> ctor = map.getClass().getConstructor();
            ctor.setAccessible(true);
            @SuppressWarnings("unchecked")
            ConcurrentHashMap<K,V> clone = (ConcurrentHashMap<K,V>) ctor.newInstance();

            // Clone each field from the old instance to the new one.
            for(Field field : map.getClass().getDeclaredFields()) {
                field.setAccessible(true);

                @SuppressWarnings("unchecked")
                ConcurrentHashMap<K,V> original = (ConcurrentHashMap<K, V>) field.get(map);

                ConcurrentHashMap<K,V> cloneOriginal = new ConcurrentHashMap<>();
                for(Map.Entry<K, V> entry : original.entrySet()) {
                    cloneOriginal.put(entry.getKey(), deepClone((ConcurrentHashMap<K, V>) entry.getValue()));
                }

                field.set(clone, cloneOriginal);
            }

            return clone;
        } catch (Exception e) {
            throw new RuntimeException("Error cloning map: " + map, e);
        }
    }
}

public class Main {

    public static void main(String[] args) throws InterruptedException {

        ConcurrentHashMap<String, MutableOrb> constellation = new ConcurrentHashMap<>();
        constellation.put("Dragon1", new MutableOrb(0, 0));
        constellation.put("Dragon2", new MutableOrb(5, 5));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(constellation);

        ExecutorService executorService = Executors.newFixedThreadPool(3); // Total of three threads: main + two additional

        Runnable task1 = () -> System.out.println("Constellations : " + tracker.getConstellations());
        Runnable task2 = () -> System.out.println("Orb for Dragon1 : " + tracker.getOrb("Dragon1"));

        executorService.execute(task1); // Thread 1
        executorService.execute(task2); // Thread 2

        executorService.shutdown();
    }
}

