class ChronomanticDragonTracker {
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(3);

    private Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        constellation = deepClone(initialConstellation);
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(constellation));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        return constellation.containsKey(sigil) ? constellation.get(sigil).clone() : null;
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) throws IllegalArgumentException {
        if (!constellation.containsKey(sigil)) throw new IllegalArgumentException();
        constellation.get(sigil).x = shimmerX;
        constellation.get(sigil).y = shimmerY;
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> initialConstellation) {
        Map<String, MutableOrb> clonedConstellation = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : initialConstellation.entrySet()) 
            clonedConstellation.put(entry.getKey(), entry.getValue().clone());
        return clonedConstellation;
    }

    public static void main(String[] args) {
        Map<String, MutableOrb> initial = new HashMap<>();
        initial.put("dragon1", new MutableOrb(5, 6));
        initial.put("dragon2", new MutableOrb(7, 8));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initial);
        Runnable task1 = () -> System.out.println(tracker.getConstellations());
        EXECUTOR.execute(task1);

        Runnable task2 = () -> System.out.println(tracker.getOrb("dragon1"));
        EXECUTOR.execute(task2);

        EXECUTOR.shutdown();
    }
}

