import java.util.stream.*;

public class MysticSeahorseTracker {
    private final Map<String, MutableShell> bubbleMap;
    private static ExecutorService executor = Executors.newFixedThreadPool(2);

    public MysticSeahorseTracker(Map<String, MutableShell> initialBubbleMap) {
        this.bubbleMap = deepReplicate(initialBubbleMap);
    }

    private static Map<String, MutableShell> deepReplicate(Map<String, MutableShell> original) {
        return original.entrySet().stream()
            .collect(Collectors.toConcurrentMap(Map.Entry::getKey, entry -> new MutableShell(entry.getValue().swirlX, entry.getValue().swirlY)));
    }

    public synchronized Map<String, MutableShell> getCurrents() {
        return deepReplicate(bubbleMap);
    }

    public synchronized MutableShell getShell(String rune) {
