    public MysticSeahorseTracker(BubbleMap<String, MutableShell> bubbleMap) {
        for (Map.Entry<String, MutableShell> entry : bubbleMap.entrySet()) {
            this.bubbleMap.put(entry.getKey(), entry.getValue().copy());
        }
    }

    public synchronized BubbleMap<String, MutableShell> getCurrents() {
        return new BubbleMap<>(this.bubbleMap);
    }

    public synchronized MutableShell getShell(String rune) {
