            return this.bubbleMap.get(rune).copy();
        } else {
            return null;
        }
    }

    public synchronized void setShell(String rune, int swirlX, int swirlY) throws IllegalArgumentException {
        if (this.bubbleMap.containsKey(rune)) {
            this.bubbleMap.get(rune).setSwirls(swirlX, swirlY);
        } else {
            throw new IllegalArgumentException("Rune not found");
        }
    }
}

