import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class AccountService {
    private static final int TIMEOUT = 1;
    private static ExecutorService executor = Executors.newFixedThreadPool(2);
    private Map<String, Account> accounts = new HashMap<>();

    public boolean transferMoney(final String accountFromId, 
            final String accountToId, 
            DollarAmount amount, 
            long timeout, 
            TimeUnit unit) throws InterruptedException {
        Account fromAccount = accounts.get(accountFromId);
        Account toAccount = accounts.get(accountToId);

        class Helper implements Runnable {
            Lock lock1;
            Lock lock2;

            public Helper(Lock lock1, Lock lock2) {
                this.lock1 = lock1;
                this.lock2 = lock2;
            }

            @Override
            public void run() {
                while (true) {
                    if (lock1.tryLock(timeout, unit)) {
                        try {
                            if (lock2.tryLock()) {
                                try {
                                    if (fromAccount.getBalance().compareTo(amount) < 0) {
                                        throw new InsufficientFundsException();
                                    } else {
                                        fromAccount.debit(amount);
                                        toAccount.credit(amount);
                                        return;
                                    }
                                } finally {
                                    lock2.unlock();
                                }
                            }
                        } finally {
                            lock1.unlock();
                        }
                    } else {
                        Thread.sleep(TIMEOUT + new Random().nextInt(TIMEOUT));
                    }
                }
            }
        }

        try {
            executor.submit(new Helper(fromAccount, toAccount)).get(timeout, unit);
            return true;
        } catch (TimeoutException | InterruptedException | ExecutionException e) {
            return false;
        } catch (InsufficientFundsException ex) {
            throw new InsufficientFundsException();
        }
    }

    static class DollarAmount implements Comparable<DollarAmount> {
        private int amount;

        public DollarAmount(int amount) {
            this.amount = amount;
        }

        @Override
        public int compareTo(DollarAmount other) {
            return Integer.compare(this.amount, other.amount);
        }

        public void debit(DollarAmount d) {
            if (d.amount > amount) throw new IllegalArgumentException();
            this.amount -= d.amount;
        }

        public void credit(DollarAmount d) {
            this.amount += d.amount;
        }
    }

    static class Account {
        private Lock lock = new ReentrantLock();
        private DollarAmount balance;

        public Account(int initialBalance) {
            this.balance = new DollarAmount(initialBalance);
        }

        public void debit(DollarAmount d) {
            lock.lock();
            try {
                balance.debit(d);
            } finally {
                lock.unlock();
            }
        }

        public void credit(DollarAmount d) {
            lock.lock();
            try {
                balance.credit(d);
            } finally {
                lock.unlock();
            }
        }

        public Lock getLock() {
            return lock;
        }

        public DollarAmount getBalance() {
            lock.lock();
            try {
                return balance;
            } finally {
                lock.unlock();
            }
        }
    }

    static class InsufficientFundsException extends RuntimeException {}
}

