class SemaphoreBasedBoundedBuffer<E> {
    private final E[] buffer;
    private int putCursor, takeCursor, count;
    private final Semaphore availableItems, remainingSpaces;

    public SemaphoreBasedBoundedBuffer(int capacity) {
        this.buffer = (E[]) new Object[capacity];
        this.putCursor = 0;
        this.takeCursor = 0;
        this.count = 0;
        this.availableItems = new Semaphore(0);
        this.remainingSpaces = new Semaphore(capacity);
    }

    public boolean isEmpty() {
        return count == 0;
    }

    public boolean isFull() {
        return count == buffer.length;
    }

    public void put(E x) throws InterruptedException {
        remainingSpaces.acquire();
        synchronized (this) {
            buffer[putCursor] = x;
            putCursor = (++putCursor == buffer.length ? 0 : putCursor);
            ++count;
        }
        availableItems.release();
    }

    public E take() throws InterruptedException {
        availableItems.acquire();
        E item;
        synchronized (this) {
            item = buffer[takeCursor];
            buffer[takeCursor] = null;
            takeCursor = (++takeCursor == buffer.length ? 0 : takeCursor);
            --count;
        }
        remainingSpaces.release();
        return item;
    }
}

