import java.math.BigInteger;
import java.util.concurrent.*;

public class ConcurrencyExample {
    public static volatile ImmutableCache cache = new ImmutableCache(null, null);

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executorService = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 10; i++) {
            BigInteger value = BigInteger.valueOf((long) (Math.random() * 3));
            Future<ImmutableCache> resultFuture = executorService.submit(() -> computeAndUpdate(value));
             try {
                cache = resultFuture.get();
                System.out.println("Updated Cache: " + cache);
             } catch (ExecutionException e) {
