import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.logging.*;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static volatile boolean debugLifecycle = false;
    private static AtomicInteger created = new AtomicInteger();
    private static AtomicInteger alive = new AtomicInteger();
    private static final Logger LOGGER = Logger.getAnonymousLogger();

    public MyAppThread(Runnable r) {
        this(r, DEFAULT_NAME);
    }

    public MyAppThread(Runnable runnable, String name) {
        super(runnable, name + "-" + created.incrementAndGet());
        setUncaughtExceptionHandler((t, e) -> LOGGER.severe(getName() + " terminated abruptly with exception: " + e));
    }

    @Override
    public void run() {
        boolean debug = debugLifecycle;
        if (debug) LOGGER.info("Created " + getName());
        try {
            alive.incrementAndGet();
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debug) LOGGER.info("Exiting " + getName());
        }
    }

    public static int getThreadsCreated() { 
        return created.get(); 
    }

    public static int getThreadAlive() { 
        return alive.get(); 
    }

    public static boolean getDebug() { 
        return debugLifecycle; 
