        locations.computeIfPresent(id, (key, val) -> new Point(x, y));
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(locations));
    }

    public static void main(String[] args) throws Exception {
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(new ConcurrentHashMap<String, Point>(){{
            put("A", new Point(0, 0));
            put("B", new Point(1, 2));
        }});

        ExecutorService executor = Executors.newFixedThreadPool(5);

        IntStream.rangeClosed(1, 3).forEach(i -> {
            final String id = "A";
            executor.submit(() -> {
                Point p;
