import java.util.*;
import java.util.concurrent.*;

class DemonstrateDeadlock {
    private static final int NUM_ACCOUNTS = 5;
    private static final int NUM_THREADS = 20;
    private static final int NUM_ITERATIONS = 100000;

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);

        List<Account> accounts = new ArrayList<>();
        for (int i = 0; i < NUM_ACCOUNTS; i++) {
            accounts.add(new Account(100));
        }

        Random random = new Random();
        for (int i = 0; i < NUM_THREADS; i++) {
            executor.execute(new TransferThread(accounts, random));
        }

        executor.shutdown();
    }

    static class Account {
        private int balance;

        public Account(int balance) {
            this.balance = balance;
        }

        public synchronized void withdraw(int amount) throws InsufficientFundsException {
            if (amount > balance) throw new InsufficientFundsException();
            balance -= amount;
        }

        public synchronized void deposit(int amount) {
            balance += amount;
        }
    }

    static class TransferThread implements Runnable {
        private final List<Account> accounts;
        private final Random random;

        public TransferThread(List<Account> accounts, Random random) {
            this.accounts = accounts;
            this.random = random;
        }

        @Override
        public void run() {
            for (int i = 0; i < NUM_ITERATIONS; i++) {
                int fromAcct = random.nextInt(NUM_ACCOUNTS);
                int toAcct = random.nextInt(NUM_ACCOUNTS);

                if (fromAcct == toAcct) continue;

                Account from = accounts.get(fromAcct);
                Account to = accounts.get(toAcct);

                int amount = random.nextInt(10);

                try {
                    DynamicOrderDeadlock.transferMoney(from, to, amount);
                } catch (InsufficientFundsException ignored) {}
            }
        }
    }

    static class InsufficientFundsException extends Exception {}

    static class DynamicOrderDeadlock {
        public static void transferMoney(Account from, Account to, int amount) throws InsufficientFundsException {
            synchronized (from) {
                synchronized (to) {
                    from.withdraw(amount);
                    to.deposit(amount);
                }
            }
        }
    }
}

