import java.util.concurrent.*;
import java.util.*;

public class StripedMap {
    private static final int N_LOCKS = 16;
    private Node[] buckets;
    private Object[] locks;

    public StripedMap(int capacity) {
        this.buckets = new Node[capacity];
        this.locks = new Object[N_LOCKS];

        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    public void put(Object key, Object value) {
        int index = hashIndex(key);
        synchronized (locks[index % N_LOCKS]) {
            Node node = buckets[index];

            while (node != null) {
                if (node.key.equals(key)) {
                    node.value = value;
                    return;
                }

                node = node.next;
            }

            Node newNode = new Node(key, value);
            newNode.next = buckets[index];
            buckets[index] = newNode;
        }
    }

    public Object get(Object key) {
        int index = hashIndex(key);
        synchronized (locks[index % N_LOCKS]) {
            Node node = buckets[index];

            while (node != null) {
                if (node.key.equals(key)) {
                    return node.value;
                }

                node = node.next;
            }
        }

        return null;
    }

    public void clear() {
        for (int i = 0; i < N_LOCKS; i++) {
            synchronized (locks[i]) {
                buckets = new Node[buckets.length];
            }
        }
    }

    private int hashIndex(Object key) {
        return Math.abs(key.hashCode() % buckets.length);
    }

    static class Node {
        Object key;
        Object value;
        Node next;

        public Node(Object key, Object value) {
            this.key = key;
            this.value = value;
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        StripedMap map = new StripedMap(16);

        ExecutorService executor = Executors.newFixedThreadPool(5);
        List<Future> futures = new ArrayList<>();

        for (int i = 0; i < 20; i++) {
            final int count = i;

            Future future = executor.submit(() -> {
                map.put("key" + count, "value" + count);
                return map.get("key" + count);
            });

            futures.add(future);
        }

        for (Future future : futures) {
            System.out.println(future.get());
        }

        executor.shutdown();
    }
}

