class StripedMap<K, V> {
    private static final int N_LOCKS = 16;

    private Node<K,V>[] buckets;
    private Object[] locks;

    public StripedMap(int capacity) {
        buckets = new Node[capacity];
        locks = new Object[N_LOCKS];

        for (int i = 0; i < N_LOCKS; ++i) {
            locks[i] = new Object();
        }
    }

    public V get(K key) {
        int hashIndex = hash(key);
        synchronized (locks[hashIndex % N_LOCKS]) {
            Node<K,V> node = buckets[hashIndex];
            while (node != null && !key.equals(node.key)) {
                node = node.next;
            }

            if (node == null) return null;
            else return node.value;
        }
    }

    public void put(K key, V value) {
        int hashIndex = hash(key);
        synchronized (locks[hashIndex % N_LOCKS]) {
            Node<K,V> node = new Node<>(key, value, buckets[hashIndex]);
            buckets[hashIndex] = node;
        }
    }

    public void clear() {
        for (int i = 0; i < N_LOCKS; ++i) {
            synchronized (locks[i]) {
                buckets = new Node[buckets.length];
            }
        }
    }

    public int size() {
        int size = 0;
        for (int i = 0; i < N_LOCKS; ++i) {
            synchronized (locks[i]) {
                Node<K,V> node = buckets[i];
                while(node != null) {
                    ++size;
                    node = node.next;
                }
            }
        }

        return size;
    }

    private int hash(Object key) {
        // This is a simple hash function and it's definitely not perfect,
        // but it serves the purpose of this example.
        return (key == null) ? 0 : Math.abs(key.hashCode()) % buckets.length;
    }

    private static class Node<K, V> {
        K key;
        V value;
        Node<K,V> next;

        public Node(K key, V value, Node<K,V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }
}

import java.util.concurrent.*;

public class StripedMap {
    private static final int N_LOCKS = 16;
    private Node[] buckets = new Node[N_LOCKS];
    private Object[] locks = new Object[N_LOCKS];

    public StripedMap() {
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int getBucketIndex(Object key) {
        return Math.abs(key.hashCode()) % N_LOCKS;
    }

    public void put(Object key, Object value) {
        Node node = new Node(key, value);
        int bucketIdx = getBucketIndex(node.getKey());
        synchronized (locks[bucketIdx]) {
            if (buckets[bucketIdx] != null) {
                Node currNode = buckets[bucketIdx];
                while (currNode != null) {
                    if (currNode.getKey().equals(key)) {
                        currNode.setValue(value);
                        return;
                    }
                    currNode = currNode.next;
                }
            }
            node.next = buckets[bucketIdx];
            buckets[bucketIdx] = node;
        }
    }

    public Object get(Object key) {
        int bucketIdx = getBucketIndex(key);
        synchronized (locks[bucketIdx]) {
            Node currNode = buckets[bucketIdx];
            while (currNode != null) {
                if (currNode.getKey().equals(key)) {
                    return currNode.getValue();
                }
                currNode = currNode.next;
            }
        }
        return null;
    }

    public void clear() {
        for (int i = 0; i < N_LOCKS; i++) {
            synchronized (locks[i]) {
                buckets[i] = null;
            }
        }
    }

    private static class Node {
        private final Object key;
        private volatile Object value;
        private Node next;

        public Node(Object key, Object value) {
            this.key = key;
            this.value = value;
        }

        public Object getKey() {
            return key;
        }

        public Object getValue() {
            return value;
        }

        public void setValue(Object newVal) {
            value = newVal;
        }
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        StripedMap map = new StripedMap();

        for (int i = 0; i < 2; i++) {
            final int index = i;
            executor.submit(() -> map.put("key" + index, "value" + index));
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        for (int i = 0; i < 2; i++) {
            System.out.println("key" + i + ": " + map.get("key" + i));
        }
    }
}

