import java.math.BigInteger;
import java.util.Arrays;
import java.util.concurrent.*;

class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public FactorCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public synchronized BigInteger[] getFactors(BigInteger number) {
        if (this.number.equals(number)) return Arrays.copyOf(factors, factors.length);
        else return null;
    }
}

class FactorComputeTask implements Callable<FactorCache> {
    private final BigInteger number;

    public FactorComputeTask(BigInteger number) { this.number = number; }

    @Override
    public FactorCache call() {
        int length = 0;
        for (BigInteger i = new BigInteger("2"); i.compareTo(this.number) <= 0; i = i.add(BigInteger.ONE)) length++;
        BigInteger[] factors = new BigInteger[length];
        int count = 0;
        for (BigInteger i = new BigInteger("1"); i.compareTo(this.number) <= 0; i = i.add(BigInteger.ONE)) {
            if (this.number.mod(i).equals(BigInteger.ZERO)) factors[count++] = i;
        }
        return new FactorCache(this.number, factors);
    }
}

public class Main {
    public static void main(String[] args) throws ExecutionException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<FactorCache> future1 = executor.submit(new FactorComputeTask(new BigInteger("60")));
        Future<FactorCache> future2 = executor.submit(new FactorComputeTask(new BigInteger("42")));
        System.out.println(Arrays.toString(future1.get().getFactors(new BigInteger("60"))));
        System.out.println(Arrays.toString(future2.get().getFactors(new BigInteger("42"))));
        executor.shutdown();
    }
