import java.math.BigInteger;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.*;

class FactorsCache {
    private final Map<BigInteger, BigInteger[]> cache = new ConcurrentHashMap<>();

    public void computeFactors(BigInteger number) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> {
            BigInteger[] factors = getFactors(number);
            cache.put(number, factors);
        });
        executor.shutdown();
    }

    public BigInteger[] getCachedFactors(BigInteger number) {
        return Arrays.copyOf(cache.getOrDefault(number, null), cache.getOrDefault(number, new BigInteger[0]).length);
    }

    private static BigInteger[] getFactors(BigInteger n) {
        BigInteger sqrt = n.sqrt();
        int numPairs = 2 * (int) Math.pow((double) sqrt.longValue(), 2) - 1;
        BigInteger[] factors = new BigInteger[numPairs];
        int i = 0;

        for (BigInteger j = BigInteger.ONE; j.compareTo(sqrt) <= 0; j = j.add(BigInteger.ONE)) {
            if (n.mod(j).equals(BigInteger.ZERO)) {
                factors[i++] = j;
                if (!j.pow(2).equals(n)) { // avoid duplication for perfect squares
                    factors[i++] = n.divide(j);
                }
            }
        }

        BigInteger[] result = new BigInteger[i];
        System.arraycopy(factors, 0, result, 0, i);
        Arrays.sort(result);
        return result;
    }
}

public class Main {
    public static void main(String[] args) throws ExecutionException, InterruptedException {
        FactorsCache cache = new FactorsCache();
        BigInteger number1 = BigInteger.valueOf(24);
        BigInteger number2 = BigInteger.valueOf(36);

        cache.computeFactors(number1);
        cache.computeFactors(number2);

        System.out.println("Factors of " + number1 + ": " + Arrays.toString(cache.getCachedFactors(number1)));
        System.out.println("Factors of " + number2 + ": " + Arrays.toString(cache.getCachedFactors(number2)));
    }
}

import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.*;

class CacheEntry {
    private final BigInteger number;
    private final List<BigInteger> factors;

    CacheEntry(BigInteger number, List<BigInteger> factors) {
        this.number = number;
        this.factors = new ArrayList<>(factors);
    }

    BigInteger getNumber() {
        return number;
    }

    List<BigInteger> getFactors() {
        synchronized (this) {
            return Collections.unmodifiableList(new ArrayList<>(factors));
        }
    }
}

class FactorizationTask implements Callable<CacheEntry> {
    private final BigInteger number;

    FactorizationTask(BigInteger number) {
        this.number = number;
    }

    @Override
    public CacheEntry call() {
        List<BigInteger> factors = new ArrayList<>();
        BigInteger i = BigInteger.valueOf(2);
        while (i.multiply(i).compareTo(number) <= 0 && !number.mod(i).equals(BigInteger.ZERO)) {
            if (number.mod(i).equals(BigInteger.ZERO)) {
                factors.add(i);
                number = number.divide(i);
            } else {
                i = i.add(BigInteger.ONE);
            }
        }
        if (number.compareTo(BigInteger.ONE) > 0) {
            factors.add(number);
        }
        return new CacheEntry(this.number, factors);
    }
}

class Cache {
    private final Map<BigInteger, List<BigInteger>> cache = new ConcurrentHashMap<>();

    List<BigInteger> getFactors(BigInteger number) throws ExecutionException, InterruptedException {
        if (cache.containsKey(number)) {
            return cache.get(number);
        }

        FactorizationTask task = new FactorizationTask(number);
        Future<CacheEntry> future = Executors.newSingleThreadExecutor().submit(task);
        CacheEntry entry = future.get();
        cache.putIfAbsent(entry.getNumber(), entry.getFactors());

        return cache.get(number);
    }
}

public class Main {
     public static void main(String[] args) throws ExecutionException, InterruptedException {
         Cache cache = new Cache();

         BigInteger num1 = new BigInteger("25");
         System.out.println("Factors of " + num1 + " are: " + cache.getFactors(num1));

         BigInteger num2 = new BigInteger("36");
         System.out.println("Factors of " + num2 + " are: " + cache.getFactors(num2));
     }
}

