import java.util.*;
import java.util.concurrent.*;

interface Account {
    void debit(DollarAmount amount) throws InsufficientFundsException;
    void credit(DollarAmount amount);
}

class DollarAmount implements Comparable<DollarAmount> {
    private final int amount;
    public DollarAmount(int amount) { this.amount = amount; }

    @Override
    public int compareTo(DollarAmount o) { return Integer.compare(this.amount, o.amount); }
}

class InsufficientFundsException extends Exception {}

class Helper {
    void transfer(Account fromAccount, Account toAccount, DollarAmount amount) throws InsufficientFundsException {
        synchronized (fromAccount) {
            synchronized (toAccount) {
                if (fromAccount.hashCode() < toAccount.hashCode()) {
                    doTransfer(fromAccount, toAccount, amount);
                } else {
                    synchronized (this) {
                        doTransfer(fromAccount, toAccount, amount);
                    }
                }
            }
        }
    }

    private void doTransfer(Account fromAccount, Account toAccount, DollarAmount amount) throws InsufficientFundsException {
        fromAccount.debit(amount);
        toAccount.credit(amount);
    }
}

class MyAccount implements Account {
    private DollarAmount balance;

    public MyAccount(DollarAmount initialBalance) { this.balance = initialBalance; }

    @Override
    synchronized public void debit(DollarAmount amount) throws InsufficientFundsException {
        if (amount.compareTo(this.balance) > 0) throw new InsufficientFundsException();
        this.balance = new DollarAmount(this.balance.compareTo(amount));
    }

    @Override
    synchronized public void credit(DollarAmount amount) {
        this.balance = new DollarAmount(this.balance.compareTo(new DollarAmount(-amount.compareTo(amount))));
    }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Account account1 = new MyAccount(new DollarAmount(20));
        Account account2 = new MyAccount(new DollarAmount(50));
        Helper helper = new Helper();

        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < 3; ++i) { // create 3 threads
            final int amount = 10;
            Future<?> future = executor.submit(() -> {
                try {
                    helper.transfer(account1, account2, new DollarAmount(amount));
                } catch (InsufficientFundsException e) {}
            });
            futures.add(future);
        }

        for (Future<?> future : futures) {
            future.get(); // wait for all threads to finish
        }
    }
}

