        balance -= amount.getValue();
    }

    public synchronized void credit(DollarAmount amount) {
        balance += amount.getValue();
    }

    public boolean hasSufficientFunds(DollarAmount amount) { return amount.getValue() <= balance; }

    @Override
    public long getValue() { return balance; }
}

