        this.to = to;
        this.amount = amount;
    }

    @Override
    public void run() {
        boolean lockOrder = from.hashCode() < to.hashCode();

        Account firstLock = lockOrder ? from : to;
        Account secondLock = !lockOrder ? from : to;

        synchronized (firstLock) {
            if (!from.hasSufficientFunds(amount)) return;

            try { Thread.sleep(10); } 
            catch (InterruptedException ignored) {}

            synchronized (secondLock) {
                from.debit(amount);
                to.credit(amount);
            }
        }
    }
}

