import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

public class ConcurrentStack {
    private static class Node<T> {
        public final T item;
        public Node<T> next;

        public Node(T item) {
            this.item = item;
        }
    }

    AtomicReference<Node<Integer>> top = new AtomicReference<>();

    public void push(Integer item) {
        Node<Integer> newHead = new Node<>(item);
        Node<Integer> oldHead;
        do {
            oldHead = top.get();
            newHead.next = oldHead;
        } while (!top.compareAndSet(oldHead, newHead));
    }

    public Integer pop() {
        Node<Integer> oldHead;
        Node<Integer> newHead;
        do {
            oldHead = top.get();
            if (oldHead == null) return null;
            newHead = oldHead.next;
        } while (!top.compareAndSet(oldHead, newHead));
        return oldHead.item;
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        ConcurrentStack stack = new ConcurrentStack();
        for (int i = 0; i < 3; i++) {
            final int taskId = i;
            Runnable task = () -> {
                for (int j = 0; j < 5; j++) {
                    System.out.println("Task " + taskId + ": Pushing " + j);
                    stack.push(j);
                }
                Integer item;
                while ((item = stack.pop()) != null) {
                    System.out.println("Task " + taskId + ": Popped " + item);
                }
            };
            executor.submit(task);
        }
        executor.shutdown();

        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("All tasks completed.");
    }
}

