import java.util.*;
import java.util.concurrent.*;

enum Species { CAT, DOG }
enum Gender { MALE, FEMALE }

class Animal {
    private final Species species;
    private final Gender gender;

    public Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    public Species getSpecies() { return species; }
    public Gender getGender() { return gender; }
}

class Pair {
    private final Animal a1, a2;

    public Pair(Animal a1, Animal a2) {
        this.a1 = a1;
        this.a2 = a2;
    }
}

class Ark {
    private final List<Pair> pairs = new ArrayList<>();

    public synchronized void addPair(Animal a1, Animal a2) {
        pairs.add(new Pair(a1, a2));
    }

    public int size() { return pairs.size(); }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Animal> animals = Arrays.asList(
            new Animal(Species.CAT, Gender.FEMALE), 
            new Animal(Species.DOG, Gender.MALE),
            new Animal(Species.CAT, Gender.MALE),
            new Animal(Species.DOG, Gender.FEMALE));

        System.out.println("Number of pairs formed: " + loadTheArk(animals));
        executor.shutdown();
    }

    public static int loadTheArk(Collection<Animal> candidates) throws InterruptedException, ExecutionException {
        Collections.sort(new ArrayList<>(candidates), Comparator.comparing(Animal::getSpecies).thenComparing(Animal::getGender));

        Ark ark = new Ark();
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < candidates.size() - 1; i += 2) {
            Animal a1 = candidates.get(i);
            Animal a2 = candidates.get(i + 1);

            if (!a1.getSpecies().equals(a2.getSpecies()) && !a1.getGender().equals(a2.getGender())) {
                futures.add(executor.submit(() -> ark.addPair(a1, a2)));
            }
        }

        for (Future<?> future : futures) {
            future.get();
        }

        return ark.size();
    }
}

