public class AnimalPairingProgram {
    private enum Species {ELEPHANT, LION, GIRAFFE}

    private enum Gender {MALE, FEMALE}

    private static class Animal {
        private final Species species;
        private final Gender gender;

        public Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        public Species getSpecies() { return species; }
        public Gender getGender() { return gender; }
    }

    private static class AnimalPair {
        private final Animal animal1, animal2;

        public AnimalPair(Animal animal1, Animal animal2) {
            this.animal1 = animal1;
            this.animal2 = animal2;
        }

        @Override
        public String toString() {
            return "{" + animal1.getSpecies()+" "+animal1.getGender() + ", " + animal2.getSpecies()+" "+animal2.getGender() + '}';
        }
    }

    private static class AnimalArk {
        private List<AnimalPair> pairs = new ArrayList<>();

        public synchronized void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        @Override
        public String toString() {
            return "AnimalArk{" + "pairs=" + pairs + '}';
        }
    }

    private static class Loader implements Runnable {
        private AnimalArk ark;
        private List<Animal> animals;

        public Loader(AnimalArk ark, List<Animal> animals) {
            this.ark = ark;
            this.animals = animals;
        }

        @Override
        public void run() {
            loadTheArk(ark, animals);
        }
    }

    private static int loadTheArk(AnimalArk ark, List<Animal> candidates) {
        Map<Species, Map<Gender, List<Animal>>> grouped = candidates.stream()
                .collect(groupingBy(Animal::getSpecies, groupingBy(Animal::getGender)));

        for (Map.Entry<Species, Map<Gender, List<Animal>>> species : grouped.entrySet()) {
            Map<Gender, List<Animal>> gender = species.getValue();

            if(gender.containsKey(Gender.FEMALE) && gender.containsKey(Gender.MALE)) {
                for (int i = 0; i < Math.min(gender.get(Gender.FEMALE).size(), gender.get(Gender.MALE).size()); i++) {
                    ark.addPair(new AnimalPair(gender.get(Gender.FEMALE).get(i), gender.get(Gender.MALE).get(i)));
                }
            }
        }

        return ark.pairs.size();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        AnimalArk ark = new AnimalArk();

        List<Animal> animals1 = Arrays.asList(new Animal(Species.ELEPHANT, Gender.FEMALE), 
                new Animal(Species.LION, Gender.MALE), new Animal(Species.GIRAFFE, Gender.FEMALE));
        List<Animal> animals2 = Arrays.asList(new Animal(Species.ELEPHANT, Gender.MALE), 
                new Animal(Species.LION, Gender.FEMALE), new Animal(Species.GIRAFFE, Gender.MALE));

        Future<?> future1 = executor.submit(new Loader(ark, animals1));
        Future<?> future2 = executor.submit(new Loader(ark, animals2));

        future1.get();
        future2.get();

        System.out.println("Pairs loaded into the ark: " + ark);
    }
}

