import java.util.concurrent.*;
import java.util.*;

public class Main {
    private static final int threadCount = 1; // Number of worker threads
    public static void main(String[] args) throws InterruptedException {
        CountDownLatch startGate = new CountDownLatch(threadCount);
        CountDownLatch endGate = new CountDownLatch(threadCount);
        ExecutorService executorService = Executors.newFixedThreadPool(threadCount);

        // Define the task for each worker thread
        Runnable task = () -> {
            try {
                startGate.countDown(); // Decrement the count of 'startGate'
                Thread.sleep(500); // Simulate a task
                endGate.countDown(); // Decrement the count of 'endGate'
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        // Submit tasks to worker threads
        for (int i = 0; i < threadCount; i++) {
            executorService.submit(task);
        }

        long start = System.nanoTime();

        startGate.await(); // Wait for all worker threads to be ready
        endGate.await(); // Wait for all worker threads to finish

        long timeTaken = System.nanoTime() - start;

        executorService.shutdownNow();

