        CountDownLatch endGate = new CountDownLatch(nThreads);

        for (int i = 0; i < nThreads; i++) {
            executor.execute(() -> {
                try {
                    startGate.await(); // Wait till all threads are ready to start.
                    task.run();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); // Preserve interrupt status on exception.
                } finally {
                    endGate.countDown();  // Notify main thread that this thread is done.
                }
            });
        }

        long start = System.nanoTime();
        startGate.countDown(); // Open the gate for all threads to start.
        endGate.await();   // Wait till all threads are done.
        executor.shutdownNow();  // Interrupt and stop all remaining threads.
