import java.util.concurrent.*;
import java.util.*;

class PrimeProducer extends Thread {
    private BlockingQueue<Integer> queue;
    private int maxPrimes;

    public PrimeProducer(BlockingQueue<Integer> queue, int maxPrimes) {
        this.queue = queue;
        this.maxPrimes = maxPrimes;
    }

    @Override
    public void run() {
        try {
            for (int i = 0; i < maxPrimes * 2 && !Thread.currentThread().isInterrupted(); i++) {
                int prime = generatePrime(i);
                queue.put(prime);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // restore interruption status
        }
    }

    private static int generatePrime(int n) {
        if(n <= 1){
            return 2;
        }

        int candidate = 1;
        for (int count = 0, i = 1; count < n; ++i) {
            if (isPrime(i)) {
                ++count;
                candidate = i;
            }
        }
        return candidate;
    }

    private static boolean isPrime(int num) {
        if(num <= 1) 
          return false;

        for (int i = 2; i <= Math.sqrt(num); ++i){
            if (num % i == 0)
                return false;
        }
        return true;
    }
}

class PrimeConsumer extends Thread {
    private BlockingQueue<Integer> queue;

    public PrimeConsumer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                Integer prime = queue.take(); // take blocks until there's something to take
                System.out.println(prime);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // restore interruption status
                break;
            }
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        int maxPrimes = 20; // can be any number you want
        BlockingQueue<Integer> queue = new LinkedBlockingDeque<>();

        PrimeProducer producer = new PrimeProducer(queue, maxPrimes);
        PrimeConsumer consumer = new PrimeConsumer(queue);

        producer.start();
        consumer.start();
        producer.join(); // wait for producer to finish producing primes
        Thread.sleep(100); // allow consumer to process remaining primes before interruption
        producer.interrupt(); // notify producer to stop producing primes

        consumer.interrupt(); // notify consumer to stop consuming primes
        consumer.join(); // wait for consumer to finish consuming all primes
    }
}

import java.util.concurrent.*;
import java.util.*;

class PrimeProducer extends Thread {
    private final BlockingQueue<Integer> queue;
    private int numOfPrimes, currentNum = 2;

    public PrimeProducer(BlockingQueue<Integer> queue, int numOfPrimes) {
        this.queue = queue;
        this.numOfPrimes = numOfPrimes;
    }

    @Override
    public void run() {
        while (!isInterrupted()) {
            if (currentNum >= numOfPrimes) break; // producer is done when it has produced the requested number of primes
            try {
                queue.put(nextPrime());
                currentNum++;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // re-set interruption status
                break; // stop if interrupted
            }
        }
    }

    private int nextPrime() {
        while (true) {
            currentNum++;
            if (isPrime(currentNum)) return currentNum;
        }
    }

    private boolean isPrime(int n) {
        for(int i = 2; i <= Math.sqrt(n); i++) 
            if(n % i == 0) return false;
        return true;
    }
}

public class Main {
