                while (true) System.out.println(queue.take()); // print the consumed prime number
            } catch (InterruptedException e) {
                if (!producer.isInterrupted()) producer.interrupt(); // stop producer thread when interrupted
            }
        });

        consumer.start();
        producer.start();
        producer.join(); 
        consumer.interrupt(); // signal producer to stop and wait for it to finish
        consumer.join(); 
    }
}

