import java.util.*;
import java.util.concurrent.*;

interface Node {
    List<Node> getChildren();
}

class ConcurrentProcessingService<T extends Element & Node> {

    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public List<Integer> processSequential(List<T> elements) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (T element : elements) {
            futures.add(executor.submit(() -> element.compute()));
        }
        executor.shutdown();
        return getResultsFromFutures(futures);
    }

    public List<Integer> processParallel(List<T> elements) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (T element : elements) {
            futures.add(executor.submit(() -> processRecursive(element)));
        }
        executor.shutdown();
        return getResultsFromFutures(futures);
    }

    private Integer processRecursive(Node node) {
        List<Future<Integer>> futures = new ArrayList<>();
        for (Node child : node.getChildren()) {
            Future<Integer> future = executor.submit(() -> processRecursive(child));
            futures.add(future);
        }
        return getResultsFromFutures(futures).stream().mapToInt(i -> i).sum();
    }

    private List<Integer> getResultsFromFutures(List<Future<Integer>> futures) throws ExecutionException, InterruptedException {
        List<Integer> results = new ArrayList<>();
        for (Future<Integer> future : futures) {
            results.add(future.get());
        }
