import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

interface Element<T> {
    T compute();
}

interface Node<T, U extends Node<?, ?>> extends Element<U[]> {}

class ExecutorServiceHelper implements AutoCloseable {
    private final ExecutorService executor;

    ExecutorServiceHelper(ExecutorService executor) { this.executor = executor; }

    @Override public void close() { executor.shutdown(); }

    <T> CompletionStage<T> submit(Supplier<T> task) {
        return CompletableFuture.supplyAsync(task, executor);
    }
}

class Main {
    private final ExecutorServiceHelper helper;

    public Main() {
        this.helper = new ExecutorServiceHelper(Executors.newFixedThreadPool(2));
    }

    <T> List<T> sequentialProcessing(List<? extends Element<T>> elements) {
        List<T> result = new ArrayList<>();
        for (Element<T> element : elements) {
            result.add(element.compute());
        }
        return result;
    }

    <T> CompletionStage<List<T>> parallelProcessing(List<? extends Element<T>> elements) {
        List<CompletionStage<T>> futures = new ArrayList<>();
        for (Element<T> element : elements) {
            futures.add(helper.submit(element::compute));
        }
        return CompletableFuture.allOf(futures.toArray(new CompletionStage[0]))
                              .thenApply(v -> futures.stream()
                                                             .map(CompletionStage::join)
                                                             .collect(Collectors.toList()));
    }

    <T extends Node<U, ?>> U sequentialRecursiveProcessing(T node) {
        List<U> results = new ArrayList<>();
        for (Element<U[]> element : node.compute()) {
            if (element instanceof Node) {
                results.addAll(Arrays.asList(sequentialRecursiveProcessing((Node<U, ?>) element)));
            } else {
                results.add(element.compute());
            }
        }
        return (U) results;
    }

    <T extends Node<U, ?>> CompletionStage<U> parallelRecursiveProcessing(T node) {
        List<CompletionStage<?>> futures = new ArrayList<>();
        for (Element<U[]> element : node.compute()) {
            if (element instanceof Node) {
                futures.add(parallelRecursiveProcessing((Node<U, ?>) element));
            } else {
                futures.add(helper.submit(element::compute));
            }
        }
        return CompletableFuture.allOf(futures.toArray(new CompletionStage[0]))
                              .thenApply(v -> futures.stream()
                                                             .map(future -> future instanceof CompletionStage ? 
                                                                       ((CompletionStage<U>) future).join() : 
                                                                       (U) future)
                                                             .collect(Collectors.toList()));
    }

    public static void main(String[] args) {
        Main program = new Main();

        List<Element<Integer>> elements = Arrays.asList(
            () -> 1,
            () -> 2,
            () -> 3
        );

        try (ExecutorServiceHelper helper = program.helper) {
            System.out.println("Sequential Processing: " + program.sequentialProcessing(elements));

            System.out.println("Parallel Processing: " + program.parallelProcessing(elements).toCompletableFuture().get());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.util.*;
import java.util.concurrent.*;

interface Element {
    int process();
}

class Node implements Element {
    private List<Element> elements;

    public Node(List<Element> elements) {
        this.elements = elements;
    }

    @Override
    public int process() {
        int sum = 0;
        for (Element element : elements) {
            sum += element.process();
        }
        return sum;
    }
}

class MyTask implements Callable<Integer> {
    private Element element;

    public MyTask(Element e) {
        this.element = e;
    }

    @Override
    public Integer call() throws Exception {
        return element.process();
    }
}

public class Main {
    static ExecutorService executor = Executors.newFixedThreadPool(2);
    static List<Future<Integer>> futures = new ArrayList<>();

    public static void main(String[] args) throws Exception {
        List<Element> list = Arrays.asList(new Node(Arrays.asList((Element) () -> 1, (Element) () -> 2)), 
                                         new Node(Arrays.asList((Element) () -> 3, (Element) () -> 4)));

        System.out.println("Sequential execution: " + seqProcess(list));
        System.out.println("Parallel execution: " + parallelProcess(list));
    }

    public static int seqProcess(List<Element> list) {
        int sum = 0;
        for (Element element : list) {
            sum += element.process();
        }
        return sum;
    }

    public static int parallelProcess(List<Element> elements) throws Exception {
        for (Element e : elements) {
            futures.add(executor.submit(new MyTask(e)));
        }

        int sum = 0;
        for (Future<Integer> future : futures) {
            sum += future.get();
        }

        executor.shutdown();
        return sum;
    }
}

