import java.util.*;
import java.util.concurrent.locks.*;

public class ReadWriteMap {
    private final Map<String, String> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final Lock readLock = lock.readLock();
    private final Lock writeLock = lock.writeLock();

    public ReadWriteMap(Map<String, String> map) {
        this.map = map;
    }

    public void put(String key, String value) {
        writeLock.lock();
        try {
            map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public String get(String key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public void remove(String key) {
        writeLock.lock();
        try {
            map.remove(key);
        } finally {
            writeLock.unlock();
        }
    }
}

import java.util.*;
import java.util.concurrent.locks.*;
import java.util.function.*;

class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(K key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    // Similar methods for remove, putAll, clear, size, containsKey, containsValue can be implemented in a similar way.
}

public class MainClass {
    public static void main(String[] args) throws InterruptedException {
        ReadWriteMap<Integer, Integer> map = new ReadWriteMap<>(new HashMap<>());

        Runnable reader1 = () -> System.out.println("Reader 1: " + map.get(1));
        Runnable reader2 = () -> System.out.println("Reader 2: " + map.isEmpty());
        Runnable writer = () -> { map.put(1, 10); System.out.println("Writer put key-value pair (1,10)"); };

        Thread[] threads = new Thread[4];
        threads[0] = new Thread(reader1);
        threads[1] = new Thread(reader2);
        threads[2] = new Thread(writer);
        threads[3] = new Thread(() -> System.out.println("Reader 3: " + map.get(1)));

        for (Thread thread : threads) {
            thread.start();
        }

        for (Thread thread : threads) {
            thread.join();
        }
    }
}

